import {CONFIG as C} from './config.js';
import {GROUPS,FOODS} from './foods.js';
import {Game,advice,clamp} from './model.js';
import {Renderer} from './render.js';
import {displayMode,dragWorldDelta} from './view.js';
const $=id=>document.getElementById(id),card=$('card'),overlay=$('overlay');
const game=new Game((Date.now()>>>0)||1);let renderer,stage='start',stageTime=0,resumeStage=null,muted=false,audio,endingReplay=false,lastHintAt=-10,hint='',lastHud=0,loaded=false,wasBalanced=false;
const keys=new Set();let drag=null;const assets={icons:{},endings:[],rider:null};
let expanded=false,changingDisplay=false,hadNativeFullscreen=false,portrait=true,rotated=false,noticeUntil=0;
const shell=$('app-shell'),fullButton=$('fullscreen');
const icon=(id,alt='')=>`<img src="assets/icons/${id}.svg" alt="${alt}">`;
$('gauges').innerHTML=GROUPS.map((g,i)=>`<div class="gauge" id="g${i}" style="--color:${g.color}" title="${g.label}">${icon(g.icon)}<div class="gauge-body"><span>${g.short}</span><div class="bar"><i></i></div></div></div>`).join('');
function screen(html,compact=false){overlay.hidden=false;card.className='card wood'+(compact?' compact':'');card.innerHTML=html;}
function setStage(next){stage=next;stageTime=0;}
function showStart(){setStage('start');$('ending').hidden=true;screen(`<span class="kicker">NUTRITION CYCLING CLUB</span><h1><em>튼튼바퀴!</em><br>식품구성자전거</h1><div class="hero-line">골고루 먹고, 신나게 달려요.</div><p>앞바퀴를 음식의 그림자에 맞춰 먹어요!<br>골고루 먹고 물도 마셔 <b>60초 안에 골인</b>하세요.</p><div class="howto"><div>${icon('carrot')}<span>골고루 먹기</span></div><div>${icon('water')}<span>물 챙기기</span></div><div>${icon('candy')}<span>간식은 적당히</span></div><div>${icon('badbread')}<span>상한 음식 피하기</span></div></div><button class="primary" id="start" ${loaded?'':'disabled'}>${loaded?'출발!':'에셋 준비 중…'}</button><p class="footnote">손가락·마우스로 위아래 드래그 · PC 방향키 ↑ ↓<br>게임의 음식 개수는 실제 영양 권장량을 뜻하지 않아요.</p>`);$('start').onclick=startRun;}
function startRun(){if(!loaded)return;resumeStage=null;endingReplay=false;game.reset();renderer.spin=0;renderer.pose=0;renderer.particles=[];hint='';lastHintAt=-10;wasBalanced=false;keys.clear();drag=null;$('ending').hidden=true;setStage('countdown');screen('<div class="countdown">3</div><p>골고루 챙길 준비, 됐나요?</p>',true);try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();}catch{}beep(440,.08);}
function beep(freq=700,duration=.06){if(muted||!audio)return;const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='square';oscillator.frequency.value=freq;gain.gain.setValueAtTime(.045,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+duration);}
function pause(reason='잠깐 쉬어 가요!'){if(!['countdown','running','finish','ending1','endingTransition','ending2'].includes(stage))return;resumeStage=stage;stage='paused';keys.clear();drag=null;$('ending').hidden=true;screen(`<span class="kicker">PAUSED</span><h2>${reason}</h2><p>시간과 음식 기록이 함께 멈췄어요.<br>준비되면 이어서 달려요.</p><button id="resume" class="primary">이어하기</button><button id="restart" class="minor">처음부터 다시</button>`,true);$('resume').onclick=resume;$('restart').onclick=startRun;}
function resume(){if(document.hidden)return;stage=resumeStage||'running';resumeStage=null;overlay.hidden=stage==='running'||stage==='finish'||stage.startsWith('ending');if(stage.startsWith('ending'))$('ending').hidden=false;else if(stage==='countdown')screen(`<div class="countdown">${Math.max(1,3-Math.floor(stageTime))}</div><p>준비, 출발!</p>`,true);}
function resizeState(){const mode=displayMode(expanded,innerWidth,innerHeight);portrait=mode.portrait;rotated=mode.rotated;shell.classList.toggle('portrait',portrait);shell.classList.toggle('landscape',!portrait);shell.classList.toggle('expanded',expanded);shell.classList.toggle('rotated',rotated);shell.style.setProperty('--shell-w',(rotated?innerHeight:innerWidth)+'px');shell.style.setProperty('--shell-h',(rotated?innerWidth:innerHeight)+'px');fullButton.textContent=expanded?'↙ 기본 화면':'⛶ 전체화면';fullButton.setAttribute('aria-label',expanded?'세로 기본 화면으로 돌아가기':'전체화면으로 가로 플레이');if(renderer)renderer.portrait=portrait;drag=null;}
function viewNotice(message){$('viewNotice').textContent=message;$('viewNotice').hidden=false;noticeUntil=performance.now()+3500;}
async function toggleFullscreen(){changingDisplay=true;try{if(expanded){const exit=document.exitFullscreen||document.webkitExitFullscreen;if((document.fullscreenElement||document.webkitFullscreenElement)&&exit)await exit.call(document);try{globalThis.screen?.orientation?.unlock?.();}catch{}expanded=false;hadNativeFullscreen=false;}else{expanded=true;resizeState();const request=shell.requestFullscreen||shell.webkitRequestFullscreen;if(request){try{await request.call(shell);hadNativeFullscreen=!!(document.fullscreenElement||document.webkitFullscreenElement);if(hadNativeFullscreen){try{await globalThis.screen?.orientation?.lock?.('landscape');}catch{}}}catch{hadNativeFullscreen=false;}}viewNotice('가로 화면으로 전환했어요. 기본 화면 버튼으로 돌아갈 수 있어요.');}}finally{changingDisplay=false;resizeState();}}
fullButton.onclick=toggleFullscreen;
function fullscreenChanged(){if(!document.fullscreenElement&&!document.webkitFullscreenElement&&hadNativeFullscreen&&!changingDisplay){expanded=false;hadNativeFullscreen=false;try{globalThis.screen?.orientation?.unlock?.();}catch{}}resizeState();}
document.addEventListener('fullscreenchange',fullscreenChanged);document.addEventListener('webkitfullscreenchange',fullscreenChanged);
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause('다녀오면 이어서 달려요');});window.addEventListener('blur',()=>{if(!changingDisplay)pause('잠깐 쉬어 가요!');});window.addEventListener('resize',resizeState);window.addEventListener('orientationchange',resizeState);
$('pause').onclick=()=>stage==='paused'?resume():pause();$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'×♪':'♪';$('sound').setAttribute('aria-label',muted?'소리 켜기':'소리 끄기');};
const canvas=$('world');
canvas.addEventListener('pointerdown',e=>{if(stage!=='running')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX||0,y:e.clientY,target:game.targetY};});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||stage!=='running')return;e.preventDefault();const delta=dragWorldDelta((e.clientX||0)-drag.x,e.clientY-drag.y,canvas.getBoundingClientRect(),portrait,rotated);game.targetY=clamp(drag.target+delta,C.bike.minY,C.bike.maxY);});
const release=e=>{if(drag?.id===e.pointerId)drag=null;};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('lostpointercapture',()=>drag=null);
document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown',' '].includes(e.key)){e.preventDefault();if(e.key===' '){if(!e.repeat)$('pause').click();}else keys.add(e.key);}});document.addEventListener('keyup',e=>keys.delete(e.key));
function setHint(text,urgent=false){if(text===hint)return;if(!urgent&&game.time-lastHintAt<2)return;hint=text;lastHintAt=game.time;$('hint').textContent=text;}
function hud(){const left=Math.max(0,Math.ceil(C.timeLimit-game.time));$('time').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;const pct=game.distance/C.finishDistance*100;$('progress').style.width=pct+'%';$('racer').style.left=pct+'%';$('distance').textContent=`골인까지 ${Math.ceil(C.finishDistance-game.distance).toLocaleString()}`;
 for(let i=0;i<7;i++){const el=$('g'+i);const value=i<5?Math.min(1,game.m.counts[i]/C.targets[i]):i===5?Math.min(1,game.m.snacks/3):game.water/100;el.querySelector('i').style.width=value*100+'%';el.classList.toggle('warn',i===5&&game.m.K||i===6&&game.water<25);}
 if(stage==='running'){if(!wasBalanced&&game.m.balanced)setHint('균형 회복! 바퀴가 튼튼해졌어요!');wasBalanced=game.m.balanced;setHint(advice(game.m,game.water));}
}
function beginEnding(replay=false){endingReplay=replay;overlay.hidden=true;$('ending').hidden=false;$('endingImage').src=assets.endings[0].src;$('endingImage').alt='분홍 조리복을 입고 정면을 향해 질주하는 사이클리스트';$('endingImage').style.opacity='1';$('endingText').textContent='전력 질주!';setStage('ending1');}
function result(){setStage(game.finishSnapshot.success?'success':'failure');$('ending').hidden=true;overlay.hidden=false;const s=game.finishSnapshot;let feedback;
 if(s.success)feedback=s.averageBalance>=.6&&s.averageImbalance<.15?'여러 식품을 골고루! 튼튼한 바퀴로 잘 달렸어요.':s.averageDry>.2?'끝까지 잘 달렸어요! 다음에는 물도 꾸준히 챙겨요.':'완주 성공! 다음에는 더 다양한 식품을 골라 봐요.';
 else if(s.averageDry>.2)feedback='이번에는 물을 더 꾸준히 챙겨 봐요!';else if(s.averageSnack>.25)feedback='이번에는 단 간식을 잠깐 쉬어 봐요!';else if(s.spoiledHits>=3)feedback='이번에는 상한 음식을 더 조심해 봐요!';else {const ratio=s.totals.slice(0,5).map((v,i)=>v/C.targets[i]);feedback=`이번에는 ${GROUPS[ratio.indexOf(Math.min(...ratio))].short}를 더 골라 봐요!`;}
 screen(`${s.hasHighSpeedEnding?'<span class="badge">⚡ 고속 완주!</span>':'<span class="kicker">RIDE COMPLETE</span>'}<h2>${s.success?'튼튼바퀴, 골인!':'아쉽게 시간 초과!'}</h2><p>${feedback}</p><div class="result-stats"><div><small>${s.success?'완주 시간':'주행 시간'}</small><strong>${s.time.toFixed(1)}<small> 초</small></strong></div><div><small>${s.success?'골인 속도':'마지막 속도'}</small><strong>${s.finishSpeedKmh}<small> km/h</small></strong></div><div><small>도달 거리</small><strong>${Math.round(s.distance)}<small> / ${C.finishDistance.toLocaleString()}</small></strong></div></div><div class="result-foods">${GROUPS.map((g,i)=>`<div>${icon(g.icon)}<span>${i===5?'단 간식':g.short}</span><b>${s.totals[i]}</b></div>`).join('')}</div><button class="primary" id="again">다시 달리기</button>${s.hasHighSpeedEnding?'<button class="minor" id="replay">엔딩 다시보기</button>':''}<button class="minor" id="home">시작 화면</button><p class="footnote">한 판 전체의 획득 기록이에요. 실제 하루 권장량이 아니에요.</p>`);$('again').onclick=startRun;$('home').onclick=()=>{game.reset();showStart();};if($('replay'))$('replay').onclick=()=>beginEnding(true);
}
$('skip').onclick=result;
function tick(dt){
 if(stage==='paused'||stage==='start'||stage==='success'||stage==='failure')return;
 if(stage==='countdown'){const old=Math.floor(stageTime);stageTime+=dt;if(stageTime>=3){setStage('running');overlay.hidden=true;beep(880,.2);}else if(Math.floor(stageTime)!==old){card.querySelector('.countdown').textContent=3-Math.floor(stageTime);beep(440,.08);}return;}
 if(stage==='running'){if(keys.has('ArrowUp'))game.targetY-=C.moveSpeed*dt;if(keys.has('ArrowDown'))game.targetY+=C.moveSpeed*dt;game.step(dt);for(const e of game.events.splice(0)){renderer.addEffect(e.food,e.y);beep(e.food.kind==='spoiled'?110:e.food.kind==='water'?1000:650+e.food.group*90,.08);if(e.food.kind==='spoiled')setHint('상한 음식! 조심해요!',true);else if(e.food.kind==='water')setHint('수분 충전! 다시 힘차게!',true);else if(e.food.kind==='snack'&&game.m.K)setHint('단 간식은 잠깐 쉬어 가요!',true);}if(game.finishSnapshot){if(game.finishSnapshot.success){setStage('finish');setHint('골인! 끝까지 잘 달렸어요!',true);beep(1100,.25);}else result();}return;}
 stageTime+=dt;
 if(stage==='finish'&&stageTime>=C.finishAnimation){if(game.finishSnapshot.hasHighSpeedEnding)beginEnding();else result();}
 else if(stage==='ending1'&&stageTime>=C.endings[0].duration){setStage('endingTransition');$('endingImage').style.opacity='0';}
 else if(stage==='endingTransition'&&stageTime>=C.endingTransition){$('endingImage').src=assets.endings[1].src;$('endingImage').alt='두 팔을 들고 골인 테이프를 통과하는 분홍 조리복 사이클리스트';$('endingImage').style.opacity='1';$('endingText').textContent='멋지게 골인!';setStage('ending2');}
 else if(stage==='ending2'&&stageTime>=C.endings[1].duration)result();
}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.src=src;im.onload=async()=>{try{await im.decode();resolve(im);}catch(e){reject(e);}};im.onerror=()=>reject(new Error(src));});}
showStart();resizeState();
Promise.all([loadImage(C.bike.sprite.path).then(im=>assets.rider=im),...FOODS.map(f=>loadImage(f.image).then(im=>assets.icons[f.id]=im)),...C.endings.map((e,i)=>loadImage(e.path).then(im=>assets.endings[i]=im)),fetch(C.bike.sprite.manifest).then(r=>r.json()).then(m=>assets.manifest=m)]).then(()=>{renderer=new Renderer(canvas,assets);loaded=true;resizeState();showStart();let last=performance.now();const loop=now=>{const dt=Math.max(0,(now-last)/1000);last=now;tick(dt);renderer.draw(game,['running','finish'].includes(stage)?dt:0,stage,stageTime);if(now>noticeUntil)$('viewNotice').hidden=true;if(now-lastHud>65){hud();lastHud=now;}requestAnimationFrame(loop);};requestAnimationFrame(loop);}).catch(e=>{$('loadError').hidden=false;$('loadError').textContent='에셋을 불러오지 못했어요. 실행 방법을 확인해 주세요: '+e.message;});
